begin;
insert into auth.users(id,email) values('dddddddd-dddd-4ddd-8ddd-ddddddddddd1','privacy@example.com');
do $$ declare u uuid:='dddddddd-dddd-4ddd-8ddd-ddddddddddd1';private_group uuid;relaxed uuid;native uuid;a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();k uuid;r jsonb;begin
 r:=public.s2a_group_create('Private group',u,'openai',1,'{"require_privacy_set":true,"is_exclusive":true,"rpm_limit":0}');private_group:=(r->>'id')::uuid;
 if private_group is null or r->>'require_privacy_set'<>'true' then raise exception 'privacy group creation failed %',r;end if;
 r:=public.s2a_group_create('Relaxed group',u,'openai',1);relaxed:=(r->>'id')::uuid;
 if r->>'require_privacy_set'<>'false' then raise exception 'privacy default changed';end if;
 r:=public.s2a_group_create('Invalid privacy group',u,'openai',1,'{"require_privacy_set":"false"}');if r->>'status'<>'400' or exists(select 1 from public.s2a_groups where name='Invalid privacy group') then raise exception 'invalid privacy partially saved';end if;
 insert into public.s2a_accounts(id,group_id,name,account_fingerprint,ciphertext,iv,priority) values(a,private_group,'Shared unknown','privacy-unknown','encrypted','iv',1),(b,private_group,'Confirmed','privacy-confirmed','encrypted','iv',50);
 insert into public.s2a_account_groups(account_id,group_id) values(a,relaxed),(b,relaxed);
 insert into public.s2a_keys(id,user_id,group_id,name,key_hash,key_prefix) values(gen_random_uuid(),u,private_group,'Strict',repeat('d',64),'prefix'),(gen_random_uuid(),u,relaxed,'Relaxed',repeat('e',64),'prefix');
 perform public.s2a_wallet_update(u,10,'set');
 r:=public.s2a_acquire(repeat('d',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');if r->>'error'<>'no_available_account' then raise exception 'unset privacy accepted %',r;end if;
 update public.s2a_accounts set extra='{"privacy_mode":"training_set_failed"}' where id=b;
 r:=public.s2a_acquire(repeat('d',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');if r->>'error'<>'no_available_account' then raise exception 'failed privacy accepted';end if;
 update public.s2a_accounts set extra='{"privacy_mode":"training_off"}' where id=b;
 r:=public.s2a_acquire(repeat('d',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');if r->'account'->>'id'<>b::text then raise exception 'private_group group did not choose confirmed account %',r;end if;
 delete from public.s2a_leases where id=(r->>'lease_id')::uuid;
 r:=public.s2a_acquire(repeat('e',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');if r->'account'->>'id'<>a::text then raise exception 'private_group gate mutated shared account globally %',r;end if;
 delete from public.s2a_leases where id=(r->>'lease_id')::uuid;
 update public.s2a_groups set require_privacy_set=false where id=private_group;
 r:=public.s2a_acquire(repeat('d',64),'gpt-4.1',gen_random_uuid(),'{}',true,null,'{}');if r->'account'->>'id'<>a::text then raise exception 'privacy gate change not effective';end if;
 delete from public.s2a_leases where id=(r->>'lease_id')::uuid;
 r:=public.s2a_group_create('Native privacy group',u,'anthropic',1,'{"require_privacy_set":true}');native:=(r->>'id')::uuid;
 insert into public.s2a_accounts(group_id,name,platform,type,account_fingerprint,ciphertext,iv) values(native,'Native','anthropic','apikey','privacy-native','encrypted','iv');
 insert into public.s2a_keys(user_id,group_id,name,key_hash,key_prefix) values(u,native,'Native',repeat('f',64),'prefix');
 r:=public.s2a_acquire(repeat('f',64),'claude-sonnet-4-20250514',gen_random_uuid(),'{}',true,null,'{}');if not(r ? 'lease_id') then raise exception 'platform without privacy setting rejected %',r;end if;
 delete from public.s2a_leases where id=(r->>'lease_id')::uuid;
 r:=public.s2a_groups_available(u);if not exists(select 1 from jsonb_array_elements(r) x where x->>'id'=native::text and x->>'require_privacy_set'='true') then raise exception 'available DTO lost requirement';end if;
end $$;
rollback;
